begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
update breeder_private.testing_access set enabled=false where singleton;
insert into auth.users(id,email,email_confirmed_at) values('e6102100-0000-4000-8000-000000000101','billing@example.test',now()),('e6102100-0000-4000-8000-000000000102','billing2@example.test',now());
insert into public.users(id,username,email,auth_user_id) values('billing-test','billingtest','billing@example.test','e6102100-0000-4000-8000-000000000101'),('billing-test2','billingtest2','billing2@example.test','e6102100-0000-4000-8000-000000000102');
insert into public.breeder_billing_prices(id,tier_code,interval,amount_cents,stripe_product,stripe_price) values('e6102100-0000-4000-8000-000000000110','HOBBY','year',4900,'prod_test','price_test');
update public.breeder_billing_settings set checkout_enabled=true;
update public.breeder_early_adopter_rules set quota=1,enabled=true where tier_code='HOBBY';
create temp table first_checkout as select public.breeder_billing_transaction('reserve','{"owner":"billing-test","offer":"e6102100-0000-4000-8000-000000000110"}') data;
select pg_temp.ok((select (data->>'early_reserved')::boolean from first_checkout),'first customer reserved');
select pg_temp.ok(not (public.breeder_billing_transaction('reserve','{"owner":"billing-test2","offer":"e6102100-0000-4000-8000-000000000110"}')->>'early_reserved')::boolean,'quota shared across pending checkouts');
select pg_temp.ok((select data->>'id' from first_checkout)=public.breeder_billing_transaction('reserve','{"owner":"billing-test","offer":"e6102100-0000-4000-8000-000000000110"}')->>'id','reserve retry idempotent');
create temp table state as select jsonb_build_object('owner','billing-test','id','sub_test','price','price_test','checkout',(select data->>'id' from first_checkout),'status','incomplete','period_end',now()+interval '1 year','observed_at',now()) data;
select public.breeder_billing_transaction('subscription',(select data from state));
select pg_temp.ok(not exists(select 1 from public.user_licenses where user_id='billing-test'),'unpaid checkout grants no license');
select public.breeder_billing_transaction('subscription',(select data||jsonb_build_object('status','active','paid_through',now()+interval '1 year','observed_at',now()+interval '1 second') from state));
select pg_temp.ok((select price_locked from public.breeder_billing_subscriptions where stripe_subscription='sub_test'),'early lock awarded');
select pg_temp.ok((select expires_at=now()+interval '1 year' from public.user_licenses where billing_reference='sub_test'),'paid term granted exactly');
select public.breeder_billing_transaction('subscription',(select data||jsonb_build_object('status','past_due','observed_at',now()+interval '2 second') from state));
select pg_temp.ok((select expires_at=now()+interval '1 year' from public.user_licenses where billing_reference='sub_test'),'failed payment does not extend or shorten term');
select public.breeder_billing_transaction('grant','{"owner":"billing-test","tier":"TOP","note":"Testing specific lifetime grant"}');
select public.breeder_billing_transaction('subscription',(select data||jsonb_build_object('status','canceled','observed_at',now()+interval '3 second') from state));
select pg_temp.ok((breeder_private.effective_license('billing-test')->>'code')='TOP','subscription cancellation preserves lifetime entitlement');
select public.breeder_billing_transaction('subscription',(select data||jsonb_build_object('status','active','paid_through',now()+interval '2 year','observed_at',now()+interval '2 second') from state));
select pg_temp.ok((select status='canceled' from public.breeder_billing_subscriptions where stripe_subscription='sub_test'),'stale event cannot resurrect cancellation');
select public.breeder_billing_transaction('revoke',jsonb_build_object('owner','billing-test','grant',(select id from public.breeder_membership_grants where owner_id='billing-test'),'note','Test removal'));
select pg_temp.ok((breeder_private.effective_license('billing-test')->>'code')='HOBBY','removing lifetime leaves paid recurring term');
select public.breeder_billing_lease('billing-test','e6102100-0000-4000-8000-000000000120',false);
do $$begin begin perform public.breeder_billing_lease('billing-test','e6102100-0000-4000-8000-000000000121',false);raise exception 'lease allowed concurrent change';exception when raise_exception then if sqlerrm not like 'Another billing change%' then raise;end if;end;end$$;
select public.breeder_billing_lease(null,'e6102100-0000-4000-8000-000000000120',true);
-- A refund arriving before checkout fulfillment must permanently withhold access.
insert into public.breeder_billing_prices(id,tier_code,interval,amount_cents,stripe_product,stripe_price) values('e6102100-0000-4000-8000-000000000130','PRO','lifetime',100000,'prod_life_test','price_life_test');
insert into public.breeder_lifetime_invitations(id,owner_id,offer_id) values('e6102100-0000-4000-8000-000000000131','billing-test2','e6102100-0000-4000-8000-000000000130');
select public.breeder_billing_transaction('block_payment','{"payment_intent":"pi_life_test","reason":"Refund arrived first"}');
select pg_temp.ok((public.breeder_billing_transaction('lifetime_paid','{"owner":"billing-test2","invitation":"e6102100-0000-4000-8000-000000000131","price":"price_life_test","session":"cs_life_test","payment_intent":"pi_life_test"}')->>'withheld')::boolean,'refund before fulfillment blocks access');
select pg_temp.ok(not exists(select 1 from public.breeder_membership_grants where stripe_payment_intent='pi_life_test'),'reversed payment creates no grant');
insert into public.breeder_lifetime_invitations(id,owner_id,offer_id) values('e6102100-0000-4000-8000-000000000132','billing-test2','e6102100-0000-4000-8000-000000000130');
select public.breeder_billing_transaction('lifetime_paid','{"owner":"billing-test2","invitation":"e6102100-0000-4000-8000-000000000132","price":"price_life_test","session":"cs_life_test2","payment_intent":"pi_life_test2"}');
select pg_temp.ok((breeder_private.effective_license('billing-test2')->>'code')='PRO','paid lifetime grants correct tier');
select public.breeder_billing_transaction('block_payment','{"payment_intent":"pi_life_test2","reason":"Refund after fulfillment"}');
select pg_temp.ok(not (breeder_private.effective_license('billing-test2')->>'active')::boolean,'refund after fulfillment removes access');
set local role authenticated;
do $$begin
 begin perform public.breeder_billing_transaction('grant','{"owner":"billing-test","tier":"TOP"}');raise exception 'client granted lifetime';exception when insufficient_privilege then null;end;
 begin perform * from public.breeder_billing_subscriptions;raise exception 'client read billing';exception when insufficient_privilege then null;end;
 begin update public.breeder_early_adopter_rules set quota=100;raise exception 'client changed quota';exception when insufficient_privilege then null;end;
end$$;
reset role;
rollback;
